const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 8471;
const CDP_PORT = 9333;
const MIME = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
